package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.springframework.dao.CannotAcquireLockException;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Real original transaction/receipt/CAS fixture. Prepared work never replaces per-transaction native verification. */
class SharedWritePreparationTest extends CatalogVersionJudgmentWriterTest {
    SharedWriteExecutor.ActionContext context(CatalogVersionJudgmentValue.Value value){return new SharedWriteExecutor.ActionContext(JdbcCatalogVersionJudgments.action(value.judgmentKey()),JdbcCatalogVersionJudgments.id(value.judgmentKey()),value.hash());}
    @Test void PreparationRunsOutsideAnyTransactionAfterOriginalReceiptLookup(){var guard=guard();var c=capture(guard);var v=value(c,true);var w=writer(guard);var calls=new AtomicInteger();var stored=f.writes.executePrepared(context(v),k->w.committed(v.judgmentKey()),()->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());calls.incrementAndGet();return a->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());return w.applyInTransaction(v,c);};});assertEquals(2L,stored.generation());assertEquals(1,calls.get());assertEquals(1,f.sends);}
    @Test void OriginalCommittedFirstSkipsPreparationEvenIfCurrentQualificationIsGone(){var guard=guard();var c=capture(guard);var v=value(c,false);var w=writer(guard);var original=apply(w,v,c);f.jdbc.update("DELETE FROM source_runs");var stored=f.writes.executePrepared(context(v),k->w.committed(v.judgmentKey()),()->{throw new AssertionError("committed first must skip preparation");});assertEquals(original.json(),stored.json());assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));}
    @Test void FailingOrNullPreparationLeavesNoPartialWriterOrReceipt(){var guard=guard();var c=capture(guard);var v=value(c,true);var w=writer(guard);assertThrows(IllegalStateException.class,()->f.writes.executePrepared(context(v),k->w.committed(v.judgmentKey()),()->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());throw new IllegalStateException("fictional pure preparation failure");}));assertThrows(IllegalStateException.class,()->f.writes.executePrepared(context(v),k->w.committed(v.judgmentKey()),()->null));assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_version_judgment'",Integer.class));}
    @Test void WholeTransactionRetryReusesPreparedWorkButRechecksNativePermission(){var guard=guard();var c=capture(guard);var v=value(c,true);var w=writer(guard);var preparations=new AtomicInteger();var executions=new AtomicInteger();var result=f.writes.executePrepared(context(v),k->w.committed(v.judgmentKey()),()->{preparations.incrementAndGet();return a->{var stored=w.applyInTransaction(v,c);if(executions.incrementAndGet()==1)throw new CannotAcquireLockException("fictional transaction retry");return stored;};});assertEquals(2L,result.generation());assertEquals(1,preparations.get());assertEquals(2,executions.get());assertEquals(2,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_version_judgment'",Integer.class));}
    @Test void AckUnknownReadsCommittedRecordWithoutRepeatingPreparation(){var guard=guard();var c=capture(guard);var v=value(c,true);var w=writer(guard);var preparations=new AtomicInteger();f.tx.ackLost=true;var stored=f.writes.executePrepared(context(v),k->w.committed(v.judgmentKey()),()->{preparations.incrementAndGet();return a->w.applyInTransaction(v,c);});assertEquals(2L,stored.generation());assertEquals(1,preparations.get());assertEquals(2,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.sends);}
    void NativeReceiptCommittedDuringPreparationIsRecheckedBeforeOriginalWriterWork()throws Exception{var guard=guard();var c=capture(guard);var v=value(c,true);var w=writer(guard);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);try(var pool=Executors.newSingleThreadExecutor()){var first=pool.submit(()->f.writes.executePrepared(context(v),k->w.committed(v.judgmentKey()),()->{entered.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IllegalStateException("fictional preparation timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return a->{throw new AssertionError("concurrent receipt must win before work");};}));assertTrue(entered.await(10,TimeUnit.SECONDS));var committed=apply(w,v,c);release.countDown();assertEquals(committed.json(),first.get(10,TimeUnit.SECONDS).json());assertEquals(2,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));}finally{release.countDown();}}
}
